# Pages a project script builds from a template (OneFile.psm1): recognised by their first line
# (<!-- Generated by SCRIPT from TEMPLATE -->) or by the build script's text, and then treated as
# output: not checked, indexed or reviewed as code, not written by Copilot, named in the context.
# Also the generator rule for any stand-in token (Lint Get-StandInToken) and the data import that
# leaves a file alone when a project script converts it itself. Made-up projects.
$root = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
$env:CCBRIDGE_STATE_ROOT = Join-Path $env:TEMP ('ccb-state-' + [guid]::NewGuid().ToString('N'))
$env:CCBRIDGE_ISSUE_INDEX = Join-Path $env:TEMP ('ccb-app-index-' + [guid]::NewGuid().ToString('N') + '.json')
foreach ($m in 'Config', 'OneFile', 'Lint', 'Guardrails', 'Executor', 'Review', 'Issues', 'DataImport', 'Health') { Import-Module (Join-Path $root "lib\$m.psm1") -Force }

function New-BuiltProject {
    $p = Join-Path $env:TEMP ('ccb-built-' + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory (Join-Path $p 'Scripts') -Force | Out-Null
    [IO.File]::WriteAllText((Join-Path $p 'report.template.html'), "<!DOCTYPE html>`n<html><head><meta charset=`"utf-8`"><title>T</title></head><body><h1>Report</h1><script>const D = /*__DATA__*/null; el.innerHTML = D.rows.join('');</script></body></html>`n")
    [IO.File]::WriteAllText((Join-Path $p 'Scripts\Build-Report.ps1'), "# Builds Report.html from the template and the CSV.`n`$ErrorActionPreference = 'Stop'`n`$html = [IO.File]::ReadAllText(`"`$PSScriptRoot\..\report.template.html`").Replace('/*__DATA__*/null', `$json)`n[IO.File]::WriteAllText(`"`$PSScriptRoot\..\Report.html`", `$html)`n")
    [IO.File]::WriteAllText((Join-Path $p 'Report.html'), "<!DOCTYPE html>`n<html><head><meta charset=`"utf-8`"><title>T</title></head><body><h1>Report</h1><script>const D = {`"rows`":[`"<p style=`"color:#ff0000`">x</p>`"]}; el.innerHTML = D.rows.join('');</script></body></html>`n")
    $p
}

Describe 'Recognising a page a script built' {
    $p = New-BuiltProject
    It 'reads the Generated line, and finds the built page through the build script without one' {
        $i = Get-GeneratedPageInfo "<!doctype html>`n<!-- Generated by build.js from page.template.html. Do not edit: change the template and run the script. -->`n<html>"
        $i.script | Should Be 'build.js'
        $i.template | Should Be 'page.template.html'
        Get-GeneratedPageInfo '<!doctype html><html><head><!-- Generated by hand --></head></html>' | Should BeNullOrEmpty   # not the first line
        $pairs = @(Get-TemplateBuildPairs ([IO.File]::ReadAllText((Join-Path $p 'Scripts\Build-Report.ps1'))))
        $pairs[0].template | Should Be 'report.template.html'
        $pairs[0].output | Should Be 'Report.html'
        $b = @(Get-TemplateBuilds $p)
        $b.Count | Should Be 1
        $b[0].output | Should Be 'Report.html'
        $b[0].script | Should Be 'Scripts/Build-Report.ps1'
        (Get-GeneratedPage $p 'Report.html').template | Should Be 'report.template.html'
        Get-GeneratedPage $p 'report.template.html' | Should BeNullOrEmpty
        Get-GeneratedPage $p 'other.html' | Should BeNullOrEmpty
        # A script that only names a template and writes nothing builds nothing.
        @(Get-TemplateBuildPairs "Write-Host 'see report.template.html and Report.html'").Count | Should Be 0
    }
    It 'keeps the built page out of the file checks, the risk and quality checks, the index and the review' {
        $built = [IO.File]::ReadAllText((Join-Path $p 'Report.html'))
        @(Get-NewFileIssues 'Report.html' '' $built $false $p).Count | Should Be 0
        $marked = "<!-- Generated by Scripts/Build-Report.ps1 from report.template.html -->`n" + $built
        @(Test-FileContent 'Report.html' $marked).Count | Should Be 0
        @(Find-RiskyCode 'Report.html' '' $marked).Count | Should Be 0
        @(Find-QualityIssues 'Report.html' '' $marked -UseKit).Count | Should Be 0
        @(Find-QualityIssues 'report.template.html' '' ([IO.File]::ReadAllText((Join-Path $p 'report.template.html'))) -UseKit).Count | Should Be 0   # the template itself is checked (and is fine)
        $rf = Get-ReviewFiles $p
        @($rf.files) -contains 'Report.html' | Should Be $false
        @($rf.files) -contains 'report.template.html' | Should Be $true
        ($rf.skipped -join "`n") | Should Match 'Report\.html \(built by Scripts/Build-Report\.ps1 from report\.template\.html\)'
        $ix = Update-IssueIndex $p
        (Read-IssueIndex $p).files.ContainsKey('Report.html') | Should Be $false
        (Read-IssueIndex $p).files.ContainsKey('report.template.html') | Should Be $true
    }
    It 'refuses a write or edit to the built page and points at the template' {
        { Assert-Writable $p 'Report.html' } | Should Throw 'built by Scripts/Build-Report.ps1 from report.template.html'
        try { Assert-Writable $p 'Report.html' } catch { $_.Exception.Message | Should Match 'change report\.template\.html and run Scripts/Build-Report\.ps1' }
        Assert-Writable $p 'report.template.html' | Should Match 'report\.template\.html$'
    }
    It 'asks a build script without the Generated line to write it, once' {
        $script = [IO.File]::ReadAllText((Join-Path $p 'Scripts\Build-Report.ps1'))
        Find-PageBuildScript 'Scripts/Build-Report.ps1' '' $script | Should Match 'builds Report\.html from report\.template\.html: make it write <!-- Generated by Build-Report\.ps1 from report\.template\.html'
        Find-PageBuildScript 'Scripts/Build-Report.ps1' $script ($script + "`n# more") | Should BeNullOrEmpty   # was already like that
        Find-PageBuildScript 'Scripts/Build-Report.ps1' '' ($script.Replace('$html)', '("<!-- Generated by Build-Report.ps1 from report.template.html -->`n" + $html))')) | Should BeNullOrEmpty
        Find-PageBuildScript 'Scripts/Other.ps1' '' "Set-Content out.txt 'x'" | Should BeNullOrEmpty
    }
    Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue
}

Describe 'A page generator with a stand-in of its own' {
    It 'finds any token swapped for < in PowerShell, JavaScript and Python, not a normal replace' {
        $ps = "`$lessThan = [string][char]60`n`$t = @'`n@@!doctype html>`n@@html lang=`"en`">@@body>Hi@@/body>@@/html>`n'@`nSet-Content index.html `$t.Replace('@@', `$lessThan)"
        Find-PlaceholderMarkup 'Work/Write-Index.ps1' $ps | Should Match 'line 3: this script writes markup with the stand-in @@ for < \(swapped for < at line 6\)'
        Find-PlaceholderMarkup 'gen.ps1' "`$h = `$h -replace '~~', [char]60`n'~~div>~~/div>'" | Should Match 'stand-in ~~'
        Find-PlaceholderMarkup 'gen.js' "html = html.replace(/%%/g, '<');`n'%%div>x%%/div>'" | Should Match 'stand-in %%'
        Find-PlaceholderMarkup 'gen.js' "const lt = String.fromCharCode(60);`nout = tpl.split('##').join(lt);`n'##!doctype html>##html>'" | Should Match 'stand-in ##'
        Find-PlaceholderMarkup 'gen.py' "page = page.replace('%%', chr(60))`n'%%html>%%body>'" | Should Match 'stand-in %%'
        Find-PlaceholderMarkup 'app.js' "s = s.replace('&amp;', '&'); el.innerHTML = '<div>' + s.replace('<', '&lt;');" | Should BeNullOrEmpty
        Find-PlaceholderMarkup 'app.js' "const html = '<div>' + name.replace(/</g, '&lt;') + '</div>';" | Should BeNullOrEmpty
        Find-PlaceholderMarkup 'tests/gen.test.js' "x.replace(/@@/g, '<'); '@@div>@@/div>'" | Should BeNullOrEmpty   # a test holds such text on purpose
    }
}

Describe 'The data import and a file the project converts itself' {
    $p = Join-Path $env:TEMP ('ccb-own-' + [guid]::NewGuid().ToString('N')); New-Item -ItemType Directory (Join-Path $p 'Scripts') -Force | Out-Null
    [IO.File]::WriteAllText((Join-Path $p 'People.csv'), "Name,Age`nAnn,41`nBob,39`n")
    It 'skips a CSV a project script reads by name and writes data from, and removes copies it made before' {
        # First the copies are made (no script yet), as before.
        $r1 = Update-DataImports $p -AppRoot $root
        @($r1.items | Where-Object { $_.status -eq 'created' }).Count | Should Be 1
        Test-Path (Join-Path $p 'data\people.json') | Should Be $true
        Test-Path (Join-Path $p 'data\people.js') | Should Be $true
        # The project gets its own converter: the copies go, the manifest says why, once.
        [IO.File]::WriteAllText((Join-Path $p 'Scripts\Build-Data.ps1'), "# Converts People.csv for the page.`n`$rows = @(Import-Csv 'People.csv')`nSet-Content 'js/people-data.js' ('window.PEOPLE = ' + (ConvertTo-Json `$rows))`n")
        (Get-ScriptOwnedSources $p @(Get-DataImportSources $p))['People.csv'] | Should Be 'Scripts/Build-Data.ps1'
        [IO.File]::SetLastWriteTimeUtc((Join-Path $p 'People.csv'), (Get-Date).ToUniversalTime().AddMinutes(1))   # the file changed: looked at again
        $r2 = Update-DataImports $p -AppRoot $root
        $it = @($r2.items | Where-Object { $_.status -eq 'script' })
        $it.Count | Should Be 1
        $it[0].note | Should Be 'Scripts/Build-Data.ps1'
        @($it[0].removed) -join ',' | Should Be 'data/people.json,data/people.js'
        Test-Path (Join-Path $p 'data\people.json') | Should Be $false
        Test-Path (Join-Path $p 'data\people.js') | Should Be $false
        (Format-DataImportNotes $r2) | Should Match "People\.csv is converted by the project's own script Scripts/Build-Data\.ps1.*earlier copies data/people\.json and data/people\.js were removed"
        Format-DataImportContext $p | Should Not Match 'people'
        @((Update-DataImports $p -AppRoot $root).items).Count | Should Be 0   # said once
        # A one-off script in Work/ does not count, nor a script that only reads the file.
        $q = Join-Path $env:TEMP ('ccb-own2-' + [guid]::NewGuid().ToString('N')); New-Item -ItemType Directory (Join-Path $q 'Work') -Force | Out-Null
        [IO.File]::WriteAllText((Join-Path $q 'People.csv'), "Name,Age`nAnn,41`n")
        [IO.File]::WriteAllText((Join-Path $q 'Work\Look.ps1'), "Import-Csv 'People.csv' | ConvertTo-Json`n")
        [IO.File]::WriteAllText((Join-Path $q 'Check.ps1'), "`$rows = Import-Csv 'People.csv'; Write-Host `$rows.Count`n")
        (Get-ScriptOwnedSources $q @(Get-DataImportSources $q)).Count | Should Be 0
        Remove-Item $q -Recurse -Force -ErrorAction SilentlyContinue
    }
    Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue
}

Describe 'Rules refined for what the dashboards showed' {
    It 'does not call a fixed innerHTML text risky, but does a variable or a line that goes on' {
        Test-LiteralHtmlAssign "cell.innerHTML = '<div class=`"kit-empty`"><p>No rows</p></div>';" | Should Be $true
        Test-LiteralHtmlAssign "sel.innerHTML = '<option value=`"`">All</option>' + '<option>x</option>';" | Should Be $true
        Test-LiteralHtmlAssign 'el.innerHTML = `<p>fixed</p>`;' | Should Be $true
        Test-LiteralHtmlAssign "sel.innerHTML = '<option>All</option>' +" | Should Be $false
        Test-LiteralHtmlAssign 'el.innerHTML = `<b>${name}</b>`;' | Should Be $false
        Test-LiteralHtmlAssign "el.innerHTML = '<a>' + name;" | Should Be $false
        @(Find-RiskyCode 'a.js' '' "cell.innerHTML = '<div class=`"kit-empty`">No rows</div>';").Count | Should Be 0
        @(Find-RiskyCode 'a.js' '' "cell.innerHTML = rows.map(r => '<p>' + r + '</p>').join('');").Count | Should Be 1
    }
    It 'tells a kit-table the page sorts itself to use the kit sorting, and a plain one that it cannot be sorted' {
        Find-UnsortedTables 'p.html' '' "<table class=`"kit-table`" id=`"tbl`"><thead><tr><th data-sort=`"name`" aria-sort=`"none`">Name</th></tr></thead></table>" | Should Match 'sorted by code of its own.*data-kit-rows="external"'
        Find-UnsortedTables 'p.html' '' '<table class="kit-table"><thead><tr><th>A</th></tr></thead></table>' | Should Match 'a table that cannot be sorted'
    }
    It 'reports a page without an h1 and a click handler a keyboard cannot reach, not a focusable one' {
        $r = @(Find-HtmlBasics 'p.html' '' "<!doctype html><html><body><p class=`"kit-header__title`">Title</p><div onclick=`"go()`">x</div><div onclick=`"go()`" tabindex=`"0`" role=`"button`">y</div><button onclick=`"go()`">z</button></body></html>")
        ($r -join "`n") | Should Match 'line 1: the page has no <h1>'
        @($r | Where-Object { $_ -match 'a clickable <div> a keyboard cannot reach' }).Count | Should Be 1
        @(Find-HtmlBasics 'p.html' '' '<!doctype html><html><body><h1>Title</h1></body></html>').Count | Should Be 0
        @(Find-HtmlBasics 'part.html' '' '<div class="card"><p>no page</p></div>').Count | Should Be 0   # a fragment, not a page
        @(Find-HtmlBasics 'App.tsx' '' 'export const App = () => <div onClick={go} tabIndex={0} role="button">x</div>;').Count | Should Be 0
    }
    It 'measures a file-level wrapper by its own statements, not by the functions inside it' {
        $wrapped = "(function () {`n  'use strict';`n" + ((1..40 | ForEach-Object { "  function f$_() {`n    return $_;`n  }" }) -join "`n") + "`n}());`n"
        @(Get-HealthIssues 'app.js' $wrapped).Count | Should Be 0
        $own = "(function () {`n  'use strict';`n" + ((1..130 | ForEach-Object { "  var v$_ = $_;" }) -join "`n") + "`n}());`n"
        @(Get-HealthIssues 'app.js' $own)[0].message | Should Match 'very long'
        $plain = "function big() {`n" + ((1..130 | ForEach-Object { "  var v$_ = $_;" }) -join "`n") + "`n}`n"
        @(Get-HealthIssues 'app.js' $plain)[0].message | Should Match "function 'big'.*very long"
    }
    It 'has the page-side checks for clickable parts a keyboard cannot reach and dates shown raw, as warnings' {
        Import-Module (Join-Path $root 'lib\Contrast.psm1') -Force
        Import-Module (Join-Path $root 'lib\CheckPolicy.psm1') -Force
        $js = Get-PageContentScript
        $js | Should Match 'kind: "keyboard"'
        $js | Should Match 'kind: "date"'
        [regex]::IsMatch($js, '[^\x00-\x7F]') | Should Be $false
        Get-CheckLevel 'index.html has 3 clickable parts a keyboard cannot reach (...)' 'script' | Should Be 'warning'
        Get-CheckLevel "index.html shows 50 dates in ISO form (such as '2026-07-16' in 'People')" 'script' | Should Be 'warning'
        Get-CheckLevel "index.html shows 2 dates with a two-digit year (such as '16 Jul 26')" 'script' | Should Be 'warning'
        Get-CheckLevel 'index.html: line 1: the page has no <h1>: put the page title in an h1' 'file' | Should Be 'warning'
    }
}

Remove-Item $env:CCBRIDGE_STATE_ROOT -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item $env:CCBRIDGE_ISSUE_INDEX -Force -ErrorAction SilentlyContinue
